请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-012

=== 用户原始指令 (query.txt) ===
我经常在外面手机突然没电导航都断了。横向排三个环形数据，中间大环显示当前电量，旁边两小环一个显示今日总用电一个显示预估剩余时长。点击天气图标能跳到天气app看是否要下雨。浅色底清爽一点，电量低于15%时大环变红色告警。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "我经常在外面手机突然没电导航都断了。横向排三个环形数据，中间大环显示当前电量，旁边两小环一个显示今日总用电一个显示预估剩余时长。点击天气图标能跳到天气app看是否要下雨。浅色底清爽一点，电量低于15%时大环变红色告警。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "battery": {
      "current": {
        "levelPercent": {
          "type": "number",
          "description": "当前手机电量百分比数值，用于主环进度。",
          "sampleValue": 12
        },
        "levelText": {
          "type": "string",
          "description": "当前手机电量展示文本。",
          "sampleValue": "12%"
        },
        "ringColor": {
          "type": "string",
          "description": "当前电量环颜色，电量低于15%时为告警红色，否则为安全绿色。",
          "sampleValue": "#ffed6f21"
        },
        "statusText": {
          "type": "string",
          "description": "电量状态提示文本。",
          "sampleValue": "低电告警"
        }
      },
      "todayUsage": {
        "valueText": {
          "type": "string",
          "description": "今日累计用电展示文本。",
          "sampleValue": "1.8度"
        },
        "ringPercent": {
          "type": "number",
          "description": "今日累计用电在小环中的归一化进度百分比。",
          "sampleValue": 45
        }
      },
      "remaining": {
        "timeText": {
          "type": "string",
          "description": "基于当前电量估算的剩余可用时长展示文本。",
          "sampleValue": "2.4h"
        },
        "ringPercent": {
          "type": "number",
          "description": "预估剩余时长在小环中的归一化进度百分比。",
          "sampleValue": 24
        }
      }
    },
    "data": {
      "weather": {
        "daily": {
          "type": "array",
          "description": "从今天开始按日期升序排列的每日天气预报。",
          "sampleValue": [
            {
              "rainProbabilityPercent": "60%"
            }
          ],
          "items": {
            "type": "object",
            "properties": {
              "rainProbabilityPercent": {
                "type": "string",
                "description": "白天降雨概率百分比。",
                "sampleValue": "60%"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_weathe2.png",
      "description": "天气图标，适用于天气应用入口和雨天出行提示，彩色 PNG。"
    }
  ]
}

